import Foundation

/// Serves the bundled fixtures (Resources/Fixtures, generated by ios/tools/make_fixtures.py from
/// data/pilot/results) and derives every list/detail endpoint from them. Used for previews and demo mode.
struct MockAPIClient: SethsterAPI {
    let details: [PerformanceDetail]
    let fixtureQuestions: [Question]
    var isDemo: Bool { true }
    var authHeaders: [String: String] { [:] }

    static let shared = MockAPIClient()

    init(bundle: Bundle = .main) {
        func load<T: Decodable>(_ name: String, as: T.Type) -> T? {
            guard let url = bundle.url(forResource: name, withExtension: "json"),
                  let data = try? Data(contentsOf: url) else { return nil }
            do { return try LiveAPIClient.decoder.decode(T.self, from: data) }
            catch { print("Fixture \(name) failed to decode: \(error)"); return nil }
        }
        let ids = load("index", as: [String].self) ?? []
        details = ids.compactMap { load($0, as: PerformanceDetail.self) }
        fixtureQuestions = load("questions", as: ItemsResponse<Question>.self)?.items ?? []
    }

    func resolve(_ path: String?) -> URL? { nil }

    private static let years: [String: String] = [
        "giuseppe-verdi": "1813–1901", "gustav-mahler": "1860–1911", "richard-wagner": "1813–1883",
        "brett-dean": "b. 1961", "claude-debussy": "1862–1918", "maurice-ravel": "1875–1937",
        "igor-stravinsky": "1882–1971", "elliott-carter": "1908–2012", "alban-berg": "1885–1935",
        "pierre-boulez": "1925–2016", "edgard-varese": "1883–1965", "bela-bartok": "1881–1945",
    ]

    var summaries: [PerformanceSummary] {
        details.map(\.asSummary).sorted { ($0.date ?? "") > ($1.date ?? "") }
    }

    private func detail(_ id: String) throws -> PerformanceDetail {
        guard let d = details.first(where: { $0.id == id }) else { throw APIError.http(404, "Not in demo data") }
        return d
    }

    func health() async throws -> Health { Health(ok: true, performances: details.count) }

    func home() async throws -> HomeResponse {
        let md = String(ISO8601DateFormatter().string(from: .now).dropFirst(5).prefix(5)) // "MM-DD"
        let otd = summaries.filter { ($0.date ?? "").dropFirst(5).prefix(5) == md }
        var cols: [String: Int] = [:]
        for s in summaries { cols[s.collection ?? "Other", default: 0] += 1 }
        let composers = try await composers()
        var spotlight: HomeSpotlight?
        if let top = composers.first {
            let items = summaries.filter { $0.composers.contains { $0.id == top.id } }
            spotlight = HomeSpotlight(
                mode: "spotlight", kind: "composer", id: top.id, name: top.name,
                eyebrow: "Today's Spotlight · Composer", title: top.name,
                subtitle: [top.years?.value, "\(items.count) broadcasts"].compactMap { $0 }.joined(separator: " · "),
                blurb: nil, imageUrl: items.first?.artworkUrl, count: items.count, items: items)
        }
        return HomeResponse(
            recent: Array(summaries.prefix(8)),
            onThisDay: otd,
            collections: cols.map { CollectionInfo(name: $0.key, count: $0.value) }.sorted { $0.name < $1.name },
            composers: composers,
            spotlight: spotlight)
    }

    func performances(_ q: PerformanceQuery) async throws -> ItemsResponse<PerformanceSummary> {
        var items = summaries
        if let c = q.collection { items = items.filter { $0.collection == c } }
        if let c = q.composer { items = items.filter { $0.composers.contains { $0.id == c } } }
        if let v = q.venue { items = items.filter { $0.venue?.id == v } }
        if let c = q.city { items = items.filter { $0.venue?.city?.caseInsensitiveCompare(c) == .orderedSame } }
        if let p = q.person {
            let ids = Set(details.filter { $0.credits.contains { $0.person.id == p } }.map(\.id))
            items = items.filter { ids.contains($0.id) }
        }
        if let y = q.year { items = items.filter { $0.date?.hasPrefix(y) == true } }
        if let text = q.q, !text.isEmpty { items = items.filter { $0.title.localizedCaseInsensitiveContains(text) } }
        if q.sort == "title" { items.sort { $0.title < $1.title } }
        if q.sort == "date" { items.reverse() }
        return ItemsResponse(items: items, total: items.count)
    }

    func performance(id: String) async throws -> PerformanceDetail { try detail(id) }

    func composers() async throws -> [ComposerSummary] {
        var map: [String: (Ref, Set<String>)] = [:]
        for d in details { for c in d.composers { map[c.id, default: (c, [])].1.insert(d.id) } }
        return map.values
            .map { ComposerSummary(id: $0.0.id, name: $0.0.name, years: Self.years[$0.0.id].map(LooseString.init),
                                   imageUrl: nil, performanceCount: $0.1.count) }
            .sorted { ($0.performanceCount ?? 0, $1.name) > ($1.performanceCount ?? 0, $0.name) }
    }

    func composer(id: String) async throws -> ComposerDetail {
        var works: [String: (ProgramItem, Set<String>)] = [:]
        var name = id
        for d in details {
            for p in d.program where p.composer?.id == id {
                name = p.composer?.name ?? name
                if let w = p.workId { works[w, default: (p, [])].1.insert(d.id) }
            }
        }
        guard !works.isEmpty else { throw APIError.http(404, "Composer not in demo data") }
        return ComposerDetail(
            id: id, name: name, years: Self.years[id].map(LooseString.init), wikidata: nil, imageUrl: nil,
            bio: nil, wikipediaUrl: nil,
            works: works.map { WorkSummary(id: $0.key, title: $0.value.0.title, composer: $0.value.0.composer,
                                           performanceCount: $0.value.1.count) }
                .sorted { $0.title < $1.title })
    }

    func work(id: String) async throws -> WorkDetail {
        let perfs = details.filter { $0.program.contains { $0.workId == id } }
        guard let item = perfs.first?.program.first(where: { $0.workId == id }) else {
            throw APIError.http(404, "Work not in demo data")
        }
        return WorkDetail(id: id, title: item.title, composer: item.composer, wikidata: nil, description: nil,
                          wikipediaUrl: nil, performances: perfs.map(\.asSummary).sorted { ($0.date ?? "") < ($1.date ?? "") })
    }

    func people(q: String?) async throws -> [PersonSummary] {
        var map: [String: (PersonRef, Int, Bool)] = [:]
        for d in details {
            for c in d.credits {
                let ensemble = ["orchestra", "chorus", "ensemble", "choir"].contains { (c.role ?? "").lowercased().contains($0) }
                map[c.person.id, default: (c.person, 0, ensemble)].1 += 1
            }
        }
        return map.values
            .filter { q == nil || q!.isEmpty || $0.0.name.localizedCaseInsensitiveContains(q!) }
            .map { PersonSummary(id: $0.0.id, name: $0.0.name, kind: $0.2 ? "ensemble" : "person",
                                 imageUrl: nil, creditCount: $0.1) }
            .sorted { $0.name < $1.name }
    }

    func person(id: String) async throws -> PersonDetail {
        var credits: [PersonCredit] = []
        var ref: PersonRef?
        for d in details {
            for c in d.credits where c.person.id == id {
                ref = c.person
                credits.append(PersonCredit(performance: d.asSummary, role: c.role, status: c.status))
            }
        }
        guard let ref else { throw APIError.http(404, "Person not in demo data") }
        return PersonDetail(id: id, name: ref.name, kind: nil, years: nil, wikidata: nil, imageUrl: nil,
                            bio: nil, wikipediaUrl: nil, credits: credits)
    }

    func venue(id: String) async throws -> VenueDetail {
        let perfs = summaries.filter { $0.venue?.id == id }
        guard let v = perfs.first?.venue else { throw APIError.http(404, "Venue not in demo data") }
        return VenueDetail(id: id, name: v.name, city: v.city, wikidata: nil, performances: perfs)
    }

    func search(q: String) async throws -> SearchResponse {
        let people = try await people(q: q)
        let composers = try await composers().filter { $0.name.localizedCaseInsensitiveContains(q) }
        var works: [String: WorkSummary] = [:]
        for d in details { for p in d.program where p.title.localizedCaseInsensitiveContains(q) {
            if let w = p.workId { works[w] = WorkSummary(id: w, title: p.title, composer: p.composer, performanceCount: nil) }
        } }
        let perfs = summaries.filter {
            $0.title.localizedCaseInsensitiveContains(q) || ($0.subtitle ?? "").localizedCaseInsensitiveContains(q)
                || ($0.venue?.name ?? "").localizedCaseInsensitiveContains(q)
        }
        return SearchResponse(performances: perfs, people: people, works: Array(works.values), composers: composers)
    }

    func questions() async throws -> [Question] { fixtureQuestions }

    // Phase 3 fixtures (make_fixtures.py saves them from the server when it has them). Missing → 404.
    private func fixture<T: Decodable>(_ name: String) throws -> T {
        guard let url = Bundle.main.url(forResource: name, withExtension: "json"),
              let data = try? Data(contentsOf: url),
              let value = try? LiveAPIClient.decoder.decode(T.self, from: data) else {
            throw APIError.http(404, "Not in demo data")
        }
        return value
    }

    func linerNotes(performanceId: String) async throws -> LinerNotes { try fixture("\(performanceId).liner-notes") }
    func transcript(performanceId: String) async throws -> Transcript { try fixture("\(performanceId).transcript") }
    func programNote(performanceId: String, n: Int) async throws -> ProgramNote { try fixture("\(performanceId).program-\(n)") }
    func versions(workId: String) async throws -> WorkVersions { try fixture("work-\(workId).versions") }

    func answer(performanceId: String, question: String, answer: String) async throws {
        try await Task.sleep(for: .milliseconds(300))
    }

    func rotation(listener: String = "default") async throws -> RotationResponse {
        let ids = await MockRotationState.shared.items(seed: Array(summaries.prefix(2).map(\.id)))
        return RotationResponse(listener: listener, items: ids.compactMap(rotationItem))
    }

    func addToRotation(performanceId: String, listener: String = "default") async throws -> RotationItem {
        guard let item = rotationItem(performanceId) else { throw APIError.http(404, "performance not found") }
        await MockRotationState.shared.add(performanceId, seed: Array(summaries.prefix(2).map(\.id)))
        return item
    }

    func removeFromRotation(performanceId: String, listener: String = "default") async throws {
        guard details.contains(where: { $0.id == performanceId }) else { throw APIError.http(404, "performance not found") }
        try await MockRotationState.shared.remove(performanceId, seed: Array(summaries.prefix(2).map(\.id)))
    }

    func reorderRotation(performanceIds: [String], listener: String = "default") async throws -> RotationResponse {
        try await MockRotationState.shared.reorder(performanceIds, seed: Array(summaries.prefix(2).map(\.id)))
        return RotationResponse(listener: listener, items: performanceIds.compactMap(rotationItem))
    }

    private func rotationItem(_ id: String) -> RotationItem? {
        guard let detail = details.first(where: { $0.id == id }) else { return nil }
        let s = detail.asSummary
        let tracks = detail.tracks.map {
            RotationTrackDownload(id: $0.id, url: $0.streamUrl, bytes: nil, format: $0.format)
        }
        return RotationItem(id: s.id, title: s.title, subtitle: s.subtitle, composers: s.composers, date: s.date,
                            dateStatus: s.dateStatus, venue: s.venue, kind: s.kind, collection: s.collection,
                            durationS: s.durationS, artworkUrl: s.artworkUrl, confirmedRatio: s.confirmedRatio,
                            addedAt: "2026-10-21T12:00:00Z", download: RotationDownload(tracks: tracks))
    }
}

private actor MockRotationState {
    static let shared = MockRotationState()
    private var ids: [String]?

    func items(seed: [String]) -> [String] {
        if ids == nil { ids = seed }
        return ids ?? []
    }

    func add(_ id: String, seed: [String]) {
        if ids == nil { ids = seed }
        if ids?.contains(id) == false { ids?.append(id) }
    }

    func remove(_ id: String, seed: [String]) throws {
        if ids == nil { ids = seed }
        guard ids?.contains(id) == true else { throw APIError.http(404, "performance not in rotation") }
        ids?.removeAll { $0 == id }
    }

    func reorder(_ order: [String], seed: [String]) throws {
        if ids == nil { ids = seed }
        guard Set(order) == Set(ids ?? []), order.count == ids?.count else {
            throw APIError.http(422, "performance_ids must contain exactly the current rotation")
        }
        ids = order
    }
}
